def test_wait_for_log() -> None:
    exporter = InMemoryLogExporter()
    query = InMemoryLogQueryClient(exporter)

    def later() -> None:
        time.sleep(0.1)
        exporter.export([at(1, "late arrival", n=2)], gzip=False, timeout_s=1)

    threading.Thread(target=later).start()
    record = query.wait_for_log(
        "arrival", timeout_s=5, interval_s=timedelta(milliseconds=20), predicate=lambda r: True
    )
    assert record.body == "late arrival"
    with pytest.raises(TimeoutError):
        wait_for_log(query, "arrival", timeout_s=0.05, interval_s=0.01, predicate=lambda r: False)


def test_wait_for_log_errors() -> None:
    class Flaky(BaseLogQueryClient):
        calls = 0

        def search(self, query: str, **kwargs: object) -> LogSearchResult:  # type: ignore[override]
            self.calls += 1
            if self.calls == 1:
                raise UnavailableError("temporarily down")
            return LogSearchResult([at(0, "ok")])

    assert wait_for_log(Flaky(), "ok", timeout_s=5, interval_s=0.01).body == "ok"

    class Denied(BaseLogQueryClient):
        def search(self, query: str, **kwargs: object) -> LogSearchResult:  # type: ignore[override]
            raise AuthenticationError("no")

    with pytest.raises(AuthenticationError):
        wait_for_log(Denied(), "x", timeout_s=1, interval_s=0.01)


