def test_polling_tail_delivers_new_records_once() -> None:
    exporter = seeded()
    query = InMemoryLogQueryClient(exporter)
    seen: list[LogRecord] = []
    tail = query.tail("", seen.append, interval_s=0.02)
    try:
        deadline = time.monotonic() + 5
        while len(seen) < 3 and time.monotonic() < deadline:
            time.sleep(0.01)
        exporter.export(
            [at(3, "same second"), at(5, "newer")], gzip=False, timeout_s=1
        )  # at(3) shares the newest timestamp
        while len(seen) < 5 and time.monotonic() < deadline:
            time.sleep(0.01)
    finally:
        tail.stop()
        tail.stop()
    assert [r.body for r in seen] == ["alpha one", "beta", "alpha three", "same second", "newer"]


def test_polling_tail_reports_errors_and_skips_old() -> None:
    errors: list[Exception] = []

    class Failing(BaseLogQueryClient):
        def search(self, query: str, **kwargs: object) -> LogSearchResult:  # type: ignore[override]
            raise UnavailableError("down")

    tail = PollingTail(Failing(), "x", lambda r: None, interval_s=0.01, on_error=errors.append)
    deadline = time.monotonic() + 5
    while not errors and time.monotonic() < deadline:
        time.sleep(0.01)
    tail.stop()
    assert isinstance(errors[0], UnavailableError)

    quiet = PollingTail(Failing(), "x", lambda r: None, interval_s=0.01)
    time.sleep(0.03)
    quiet.stop()

    got: list[LogRecord] = []
    source = InMemoryLogQueryClient(seeded())
    later = PollingTail(source, "", got.append, interval_s=10, start=T0 + timedelta(seconds=2))
    later.stop()
    later.poll_once()
    assert later.poll_once() == 0  # nothing is delivered twice
    assert [r.body for r in got] == ["beta", "alpha three"]


